{
  "aggregate": "question",
  "pipeline": {{
    (() => {
      const targetDomains = this.params.domains || [];
      const onlyWrong = this.params.onlyWrong === true || this.params.onlyWrong === "true";

      let matchConditions = {};

      // Wenn ein Array übergeben wird:
      if (Array.isArray(targetDomains)) {
        if (targetDomains.length > 0) {
          // Normaler Filter mit den gewählten Domains
          matchConditions["domain"] = { "$in": targetDomains };
        } else {
          // WICHTIG: Wenn das Array leer ist, matche gar nichts (liefert leeres Ergebnis)
          matchConditions["domain"] = { "$in": [] };
        }
      } else if (typeof targetDomains === "string" && targetDomains.trim() !== "") {
        matchConditions["domain"] = targetDomains;
      }

      // 2. Zusätzlicher Filter für countWrong > 0, falls true
      if (onlyWrong) {
        matchConditions["countWrong"] = { "$exists": true, "$gt": 0 };
      }

      let pipeline = [];

      // `$match` wird jetzt immer ausgeführt, da matchConditions nie leer ist
      pipeline.push({
        "$match": matchConditions
      });

      // Danach nach Domain gruppieren und zählen
      pipeline.push(
        {
          "$group": {
            "_id": "$domain",
            "total": { "$sum": 1 }
          }
        },
        {
          "$sort": { "_id": 1 }
        }
      );

      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": 100
  }
}
